#include "core.hpp"
#include <cassert>
#include <cstdio>
#include <fstream>
#include <string>
#include <vector>
using namespace chronocyd;
static void le(std::ostream& f,unsigned v,unsigned n){while(n--){f.put(char(v&255));v>>=8;}}
static void wav(const std::string& name,const std::vector<int16_t>& b){std::ofstream f(name,std::ios::binary);f.write("RIFF",4);le(f,36+unsigned(b.size()*2),4);f.write("WAVEfmt ",8);le(f,16,4);le(f,1,2);le(f,1,2);le(f,rate,4);le(f,rate*2,4);le(f,2,2);le(f,16,2);f.write("data",4);le(f,unsigned(b.size()*2),4);for(auto v:b)le(f,uint16_t(v),2);assert(f);}
static void ppm(const std::string& name,const Engine& e){std::ofstream f(name,std::ios::binary);f<<"P6\n320 240\n255\n";for(int y=0;y<240;++y){uint16_t buf[320];row(e,y,buf);for(auto c:buf){f.put(char((c>>11)*255/31));f.put(char(((c>>5)&63)*255/63));f.put(char((c&31)*255/31));}}assert(f);}
static std::vector<int16_t> phrase(Engine& e,unsigned preset,unsigned block,bool edit){e.reset(preset);e.playing=true;Touch t;std::vector<int16_t> b(rate*8);for(unsigned begin=0;begin<b.size();){if(begin==rate*2){t.input(e,true,255,12);t.input(e,false,0,0);}if(begin==rate*4&&edit){t.input(e,true,32,75);t.input(e,true,250,75);t.input(e,false,0,0);e.recall(factory[(preset+1)%4]);}if(begin==rate*7)e.stop();unsigned n=std::min({block,unsigned(b.size())-begin,rate-begin%rate});e.render(b.data()+begin,n);begin+=n;}return b;}
int main(int argc,char** argv){Engine e,f;unsigned peak=0,changed=0;for(unsigned p=0;p<4;++p){auto a=phrase(e,p,128,true),b=phrase(f,p,17,true);assert(a==b);assert(e.master==f.master);assert(e.lane[1].ticks==f.lane[1].ticks);for(auto v:a)peak=std::max(peak,unsigned(v<0?-int(v):v));for(unsigned i=rate*7;i<a.size();++i)assert(!a[i]);auto c=phrase(f,p,128,false);assert(a!=c);for(unsigned i=0;i<a.size();++i)changed+=a[i]!=c[i];if(argc>1){std::string prefix=std::string(argv[1])+"/scene"+std::to_string(p);wav(prefix+".wav",a);ppm(prefix+".ppm",e);}}
 assert(peak<24576&&peak>1000);e.reset(0);e.playing=true;for(unsigned i=0;i<rate;++i)e.sample();auto clock=e.lane[1].clock;auto s=e.s;s.bpm=170;s.warp=-60;assert(e.recall(s)&&e.lane[1].clock==clock);s.lengths[0]=0;assert(!e.recall(s));Touch t;t.input(e,true,0,50);t.input(e,true,319,50);auto mask=e.s.masks[0];assert(mask==0||mask==127);t.input(e,true,0,50);assert(e.s.masks[0]==mask);t.input(e,false,0,0);t.input(e,true,319,220);assert(!e.playing&&e.sample()==0);t.input(e,true,0,50);assert(e.s.masks[0]==mask);t.input(e,false,0,0);e.reset(0);f=e;e.playing=f.playing=true;f.s.warp=0;unsigned warpDiff=0;for(unsigned i=0;i<rate*8;++i)warpDiff+=e.sample()!=f.sample();assert(warpDiff>rate&&e.lane[0].ticks==f.lane[0].ticks&&e.lane[0].clock==f.lane[0].clock);for(unsigned i=0;i<10000;++i){t.input(e,true,int(i%340)-10,int(i%250)-5);t.input(e,false,0,0);e.sample();}std::printf("PASS 768000 partition-equivalent samples; changed=%u warpDiff=%u peak=%u Engine=%zu Touch=%zu\n",changed,warpDiff,peak,sizeof(Engine),sizeof(Touch));}
